LINE_TYPES = ['cost_purchased_finished_goods', 'variable_overhead_landed_costs', 'add_back_fixed_overhead',
              'less_variable_operating_expense', 'selling_general_administrative', 'total_operating_expenses',
              'interest_expense', 'taxes']


def ensure_lines(budget):
    if budget.x_line_ids:
        return
    values = []
    sequence = 0
    for line_type in LINE_TYPES:
        sequence += 10
        values.append({'x_budget_id': budget.id, 'x_sequence': sequence, 'x_line_type': line_type, 'x_percentage': 0.0})
    env['x_isr_budget_line'].sudo().create(values)

for budget in records:
    ensure_lines(budget)
    if (budget.x_sales_revenue or 0) <= 0:
        raise UserError("Cannot confirm a budget with zero sales revenue.")
    has_pct = False
    for line in budget.x_line_ids:
        if line.x_percentage:
            has_pct = True
    if not has_pct:
        raise UserError("Cannot confirm a budget when all budget lines have zero percent and calculated amounts are all zero.")
    if env['x_isr_budget'].sudo().search_count([('x_year', '=', budget.x_year), ('x_quarter', '=', budget.x_quarter),
                                               ('x_company_id', '=', budget.x_company_id.id), ('id', '!=', budget.id)]):
        raise UserError("Year %s already has a budget for %s for this company. Each quarter (Q1-Q4) can only be used once per year per company."
                        % (budget.x_year, (budget.x_quarter or '').upper()))
    budget.write({'x_state': 'confirmed'})

# The old module's install hook: for every company and row without a mapping,
# the accounts with the standard codes.
CODES = {
    'sales_revenue': ['04.1.101', '04.1.102', '04.1.104'],
    'cost_purchased_finished_goods': ['05.1.101', '05.1.102', '05.1.103', '05.1.104', '05.1.105', '05.2.101', '05.2.102', '05.1.1.104', '500000'],
    'variable_overhead_landed_costs': ['05.1.113', '06.1.302', '05.1.106', '220110', '06.1.304', '220100'],
    'add_back_fixed_overhead': ['01.1.116', '230200', '06.2.505', '06.2.604', '220601', '06.2.605', '220600', '220900', '06.2.613'],
    'less_variable_operating_expense': ['06.2.611', '240101', '06.2.201', '212300', '06.2.503', '620000'],
    'interest_expense': ['06.2.203'],
    'taxes': ['230150'],
}
created = 0
for company in env['res.company'].sudo().search([]):
    for row_key in CODES:
        if env['x_isr_mapping'].sudo().search_count([('x_company_id', '=', company.id), ('x_row_key', '=', row_key)]):
            continue
        accounts = env['account.account'].sudo().search([('company_id', '=', company.id), ('code', 'in', CODES[row_key])])
        if accounts:
            env['x_isr_mapping'].sudo().create({'x_company_id': company.id, 'x_row_key': row_key, 'x_account_ids': [(6, 0, accounts.ids)]})
            created += 1
if not env.context.get('isr_quiet'):
    action = {'type': 'ir.actions.client', 'tag': 'display_notification',
              'params': {'title': 'Income Statement Accounts', 'type': 'success', 'message': '%s mapping(s) created.' % created}}
